const DepotRenderer=globalThis.DepotRenderer;
// Keep the shared puzzle, chapter and camera. The Depot owns only its artwork.
const depotNativeOutput={canvas:paperOutputCanvas,scale:paperOutputScale};
const depotScene={level:null,chutes:null,traces:[],gateTrace:null,elapsed:0,mode:'edit'};
const depotTraces=[];
const depotChapter={mode:'',time:0};
const depotTile=16/DepotProjection.HW;
let depotRenderer=null,depotCanvas=null,depotDensity=1,depotOutput=false;
function depotRead(){
 const demo=cpActive()&&CP.mode==='demo'&&CP.demo;
 depotScene.level=demo?demo.level:gm.L;
 depotScene.chutes=demo?demo.turns:gm.chutes;
 const traces=demo?demo.traces:G_TRACES;
 const count=demo?traces.length:gRunning()?gm.sim.n:0;
 const local=depotScene.traces;
 local.length=count;
 for(let i=0;i<count;i++){
  const trace=traces[i];
  let sample=depotTraces[i];
  if(!sample||Object.getPrototypeOf(sample)!==trace){
   sample=depotTraces[i]=Object.create(trace);sample.ox=sample.oy=0;
  }
  local[i]=sample;
 }
 depotScene.gateTrace=demo?demo.gates:gm.gateTrace;
 depotScene.elapsed=demo?(CP.frame%(demo.loop*60))/60:gm.t;
 depotScene.mode=demo?'running':gm.mode;
}
function scopeScale(){return cpActive()&&CP.mode==='enter'?CP.visualScale:scale;}
function depotDraw(){
 depotOutput=false;
 if(!depotRenderer?.ready||!gm.L||!GAME_MODE||!G_KEEP_PROGRESS||gm.custom||paperAtlasBuilding)return false;
 depotRead();
 depotDensity=Math.max(paperRenderScale(),Math.min(4,Math.ceil(scopeScale())));
 const width=LW*depotDensity,height=LH*depotDensity;
 if(depotCanvas.width!==width||depotCanvas.height!==height){
  depotCanvas.width=width;depotCanvas.height=height;
 }
 const r=depotRenderer;
 r.config.width=LW;r.config.height=LH;r.dpr=depotDensity;
 r.cam.scale=depotTile;
 r.cam.tx=OX+DEPOT_DATA.board.x-DEPOT_DATA.board.y-viewX-760*depotTile;
 r.cam.ty=OY+(DEPOT_DATA.board.x+DEPOT_DATA.board.y)/2-viewY-465*depotTile;
 r.motion=!document.hidden&&!document.documentElement.classList.contains('reduced');
 if(r.motion)r.ambient=loopT;
 r.gray=grayscale;
 const mode=cpActive()?CP.mode:'';
 // The canonical entry animates the complete raster using its existing endpoints.
 depotChapter.mode=mode==='growth'?(CP.stage===1?'growth1':'growth2'):mode==='exit'?'exit':'';
 depotChapter.time=CP.frame/60;
 r.chapter=depotChapter;
 r.draw(depotScene);depotOutput=true;return true;
}
return {
 async mount(){
  api.check();
  const canvas=document.createElement('canvas');
  const owner=new DepotRenderer(canvas,DepotAssets,true);
  depotCanvas=canvas;depotRenderer=owner;
  try{await owner.load();api.check();if(gm.L){depotRead();owner.prepare(depotScene);}}
  catch(error){owner.hallImages?.details?.close?.();throw error;}
  paperOutputCanvas=()=>depotOutput?canvas:depotNativeOutput.canvas();
  paperOutputScale=()=>depotOutput?depotDensity:depotNativeOutput.scale();
  api.hooks({render:depotDraw,smooth:true});
  dirty=true;
 },
 refresh(){api.check();if(gm.L){depotRead();depotRenderer.prepare(depotScene);}dirty=true;},
 dispose(){
  depotOutput=false;
  depotRenderer?.hallImages?.details?.close?.();
  depotRenderer=null;
  if(depotCanvas)depotCanvas.width=depotCanvas.height=1;
  depotCanvas=null;
 },
 resources(){
  if(!depotRenderer)return {bytes:0};
  let bytes=0;
  for(const image of Object.values(depotRenderer.images))bytes+=image.naturalWidth*image.naturalHeight*4;
  return {bytes,scope:'decoded source images; excludes canvas, browser and process peak'};
 }
};
